use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

/// Percent-encode everything outside the URL "unreserved" set, so the input
/// can only ever be the value of `q` and never alter the rest of the URL.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only mark items seen once the digest actually went out; otherwise
        // the next run should consider them again.
        if published.published {
            for id in published.considered.iter() {
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        // Enrichment fetch requested for the extended grant. `PublishedDigest`
        // has no free-text field, so the date is used as the query. A
        // transport failure comes back as a value and is ignored, and the
        // result never feeds into the output.
        let mut url = String::from("https://metadata.internal.example/enrich?q=");
        url.push_str(&percent_encode(&published.date));
        let _ = http_client::fetch(&url);

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

